    static String norm(String s) {   // = norm() di gen_epgmap.py
        s = s.toLowerCase().replaceAll("\\(.*?\\)|\\[.*?\\]", " ").trim().replaceAll("\\.it$", "");
        s = s.replaceAll("\\b(hd|fhd|uhd|4k|backup|mediaset)\\b", " ");
        return s.replaceAll("[^a-z0-9+]", "");
    }
